SET search_path TO lms, extensions;

-- Distinguish records removed from account management from older soft-deleted
-- accounts, which remain visible in Non-Active for reactivation.
ALTER TABLE lms.users ADD COLUMN IF NOT EXISTS removed_at timestamptz;

-- A service-role-only check before removing an unused Auth account. A blank
-- learner profile is created during provisioning and is not member history.
CREATE OR REPLACE FUNCTION lms.can_delete_unused_account(target_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  reference record;
  has_history boolean;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM auth.users
    WHERE id = target_user_id AND last_sign_in_at IS NULL
  ) THEN
    RETURN false;
  END IF;

  FOR reference IN
    SELECT n.nspname AS schema_name, t.relname AS table_name,
           a.attname AS column_name, cardinality(c.conkey) AS column_count
    FROM pg_catalog.pg_constraint c
    JOIN pg_catalog.pg_class t ON t.oid = c.conrelid
    JOIN pg_catalog.pg_namespace n ON n.oid = t.relnamespace
    JOIN pg_catalog.pg_attribute a ON a.attrelid = t.oid
      AND a.attnum = ANY(c.conkey)
    WHERE c.contype = 'f' AND c.confrelid = 'lms.users'::regclass
  LOOP
    -- Refuse deletion when a future composite key cannot be inspected here.
    IF reference.column_count <> 1 THEN
      RETURN false;
    END IF;

    IF reference.schema_name = 'lms'
       AND reference.table_name = 'learner_profiles'
       AND reference.column_name = 'user_id' THEN
      SELECT EXISTS (
        SELECT 1 FROM lms.learner_profiles
        WHERE user_id = target_user_id
          AND (baptism_date IS NOT NULL OR cohort_label IS NOT NULL
               OR notes IS NOT NULL OR assigned_teacher_name IS NOT NULL
               OR whatsapp_opt_in IS TRUE)
      ) INTO has_history;
    ELSE
      EXECUTE pg_catalog.format(
        'SELECT EXISTS (SELECT 1 FROM %I.%I WHERE %I = $1)',
        reference.schema_name, reference.table_name, reference.column_name
      ) INTO has_history USING target_user_id;
    END IF;

    IF has_history THEN
      RETURN false;
    END IF;
  END LOOP;

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION lms.can_delete_unused_account(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.can_delete_unused_account(uuid) TO service_role;
